113	impl<T: Ord> SortedSet<T> {
114	    /// Inserts `value`, reporting `true` when it was not already present.
115	    pub fn insert(&mut self, value: T) -> bool {
116	        self.list.insert_if_absent(value)
117	    }
118	
119	    /// Inserts `value`, returning the value it displaced when already present.
120	    pub fn replace(&mut self, value: T) -> Option<T> {
121	        self.list.insert_or_replace(value)
122	    }
123	
124	    /// Returns `true` when `value` is a member of the set.
125	    pub fn contains(&self, value: &T) -> bool {
126	        self.list.contains(value)
127	    }
128	
129	    /// Removes `value`, reporting whether it was present.
130	    pub fn remove(&mut self, value: &T) -> bool {
131	        self.list.remove(value)
132	    }
133	
134	    /// Rank of `value`, if present.
135	    pub fn index_of(&self, value: &T) -> Option<usize> {
136	        self.list.index_of(value)
137	    }
138	
139	    /// Rank of the first value not less than `value`.
140	    pub fn bisect_left(&self, value: &T) -> usize {
141	        self.list.bisect_left(value)
142	    }
143	
144	    /// Rank of the first value greater than `value`.
145	    pub fn bisect_right(&self, value: &T) -> usize {
146	        self.list.bisect_right(value)
147	    }
148	
149	    /// Inserts every item from `items`.
150	    pub fn extend_from<I: IntoIterator<Item = T>>(&mut self, items: I) {
151	        for value in items {
152	            self.insert(value);
153	        }
154	    }
155	
156	    /// Values present in `self` or `other`.
157	    pub fn union_with(&self, other: &SortedSet<T>) -> SortedSet<T>
158	    where
159	        T: Clone,
160	    {
161	        let mut merged = Vec::with_capacity(self.len() + other.len());
162	        self.merge_walk(other, |ordering| ordering != Ordering::Greater, true, &mut merged);
163	        SortedSet::from_sorted_unique(merged, self.load_factor())
164	    }
165	
166	    /// Values present in both `self` and `other`.
167	    pub fn intersection_with(&self, other: &SortedSet<T>) -> SortedSet<T>
168	    where
169	        T: Clone,
170	    {
171	        let mut merged = Vec::with_capacity(self.len().min(other.len()));
172	        self.merge_walk(other, |ordering| ordering == Ordering::Equal, false, &mut merged);
173	        SortedSet::from_sorted_unique(merged, self.load_factor())
174	    }
175	
176	    /// Values present in `self` but not in `other`.
177	    pub fn difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
178	    where
179	        T: Clone,
180	    {
181	        let mut merged = Vec::with_capacity(self.len());
182	        self.merge_walk(other, |ordering| ordering == Ordering::Less, false, &mut merged);
183	        SortedSet::from_sorted_unique(merged, self.load_factor())
184	    }
185	
186	    /// Values present in exactly one of `self` and `other`.
187	    pub fn symmetric_difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
188	    where
189	        T: Clone,
190	    {
191	        let mut merged = Vec::with_capacity(self.len() + other.len());
192	        self.merge_walk(other, |ordering| ordering != Ordering::Equal, true, &mut merged);
193	        SortedSet::from_sorted_unique(merged, self.load_factor())
194	    }
195	
196	    /// Walks both sorted sequences once, collecting the values that qualify.
197	    ///
198	    /// `keep` is asked about each value from `self` using how it compares to the
199	    /// current value from `other` (`Less` means "only in `self`", `Equal` means
200	    /// "in both"). `keep_other_only` decides whether values found solely in
201	    /// `other` are collected.
202	    fn merge_walk<F>(
203	        &self,
204	        other: &SortedSet<T>,
205	        keep: F,
206	        keep_other_only: bool,
207	        out: &mut Vec<T>,
208	    ) where
209	        T: Clone,
210	        F: Fn(Ordering) -> bool,
211	    {
212	        let mut left = self.iter().peekable();
213	        let mut right = other.iter().peekable();
214	        loop {
215	            // Decide first so the `peek` borrows end before we advance either side.
216	            let step = match (left.peek(), right.peek()) {
217	                (Some(a), Some(b)) => Some(a.cmp(b)),
218	                (Some(_), None) => Some(Ordering::Less),
219	                (None, Some(_)) => Some(Ordering::Greater),
220	                (None, None) => None,
221	            };
222	            match step {
223	                None => return,
224	                Some(Ordering::Less) => {
225	                    let a = left.next().expect("just peeked");
226	                    if keep(Ordering::Less) {
227	                        out.push(a.clone());
228	                    }
229	                }
230	                Some(Ordering::Greater) => {
231	                    let b = right.next().expect("just peeked");
232	                    if keep_other_only {
233	                        out.push(b.clone());
234	                    }
235	                }
236	                Some(Ordering::Equal) => {
237	                    let a = left.next().expect("just peeked");
238	                    right.next();
239	                    if keep(Ordering::Equal) {
240	                        out.push(a.clone());
241	                    }
242	                }
243	            }
244	        }
245	    }
246	
247	    /// Returns `true` when every value of `self` is also in `other`.
248	    pub fn is_subset_of(&self, other: &SortedSet<T>) -> bool {
249	        if self.len() > other.len() {
250	            return false;
251	        }
252	        let mut right = other.iter();
253	        for value in self.iter() {
254	            loop {
255	                match right.next() {
256	                    // Skip past values that `other` has and `self` does not.
257	                    Some(candidate) if candidate < value => continue,
258	                    Some(candidate) if candidate == value => break,
259	                    // Either `other` moved past `value` or it ran out.
260	                    _ => return false,
261	                }
262	            }
263	        }
264	        true
265	    }
266	
267	    /// Returns `true` when every value of `other` is also in `self`.
268	    pub fn is_superset_of(&self, other: &SortedSet<T>) -> bool {
269	        other.is_subset_of(self)
270	    }
271	
272	    /// Returns `true` when the two sets share no values.
273	    pub fn is_disjoint_from(&self, other: &SortedSet<T>) -> bool {
274	        let mut left = self.iter().peekable();
275	        let mut right = other.iter().peekable();
276	        loop {
277	            // Resolve the comparison before advancing, to release the borrows.
278	            let step = match (left.peek(), right.peek()) {
279	                (Some(a), Some(b)) => a.cmp(b),
280	                _ => return true,
281	            };
282	            match step {
283	                Ordering::Less => {
284	                    left.next();
285	                }
286	                Ordering::Greater => {
287	                    right.next();
288	                }
289	                Ordering::Equal => return false,
290	            }
291	        }
292	    }
293	}
