419	    #[test]
420	    fn union_matches_the_test6_scenario() {
421	        // Mirrors tests/test6: {0..n-1} unioned with {0, 2, ..., 2n-2}.
422	        for n in 0..40i32 {
423	            let mut s1 = SortedSet::new();
424	            let mut s2 = SortedSet::new();
425	            for i in 0..n {
426	                s1.insert(i);
427	                s2.insert(i * 2);
428	            }
429	            let s3 = s1.union_with(&s2);
430	
431	            let mut expected: Vec<i32> = (0..n).collect();
432	            for i in 0..n {
433	                if !expected.contains(&(i * 2)) {
434	                    expected.push(i * 2);
435	                }
436	            }
437	            expected.sort();
438	            assert_eq!(s3.to_vec(), expected, "n = {n}");
439	            assert_eq!(s1.len(), n as usize);
440	            assert_eq!(s2.len(), n as usize);
441	            for i in 0..n {
442	                assert!(s3.contains(&i), "n = {n}, contains({i})");
443	            }
444	        }
445	    }
