448	    fn union_is_symmetric_and_absorbs_duplicates() {
449	        let a = set_of(&[1, 3, 5, 7]);
450	        let b = set_of(&[3, 4, 5, 6]);
451	        let expected = vec![1, 3, 4, 5, 6, 7];
452	        assert_eq!(a.union_with(&b).to_vec(), expected);
