463	    fn intersection_difference_and_symmetric_difference() {
464	        let a = set_of(&[1, 2, 3, 4, 5]);
465	        let b = set_of(&[4, 5, 6, 7]);
466	        assert_eq!(a.intersection_with(&b).to_vec(), vec![4, 5]);
467	        assert_eq!(b.intersection_with(&a).to_vec(), vec![4, 5]);
