485	    #[test]
486	    fn subset_superset_and_disjoint() {
487	        let a = set_of(&[1, 2, 3]);
488	        let b = set_of(&[1, 2, 3, 4, 5]);
489	        let c = set_of(&[9, 10]);
490	        let empty = SortedSet::<i32>::new();
491	
492	        assert!(a.is_subset_of(&b));
493	        assert!(!b.is_subset_of(&a));
494	        assert!(b.is_superset_of(&a));
495	        assert!(a.is_subset_of(&a));
496	        assert!(empty.is_subset_of(&a));
497	        assert!(!a.is_subset_of(&empty));
498	
499	        assert!(a.is_disjoint_from(&c));
500	        assert!(c.is_disjoint_from(&a));
501	        assert!(!a.is_disjoint_from(&b));
502	        assert!(empty.is_disjoint_from(&a));
503	
504	        // A same-size, non-matching set must not read as a subset.
505	        assert!(!set_of(&[1, 2, 4]).is_subset_of(&a));
506	        // A value below every member of the other set must fail fast.
507	        assert!(!set_of(&[0]).is_subset_of(&a));
508	        // A value above every member must fail too.
509	        assert!(!set_of(&[4]).is_subset_of(&a));
510	    }
