512	    #[test]
513	    fn set_algebra_matches_a_brute_force_model() {
514	        // Exhaustive over all subsets of 0..6 -- every overlap pattern.
515	        for left_bits in 0u32..64 {
516	            for right_bits in 0u32..64 {
517	                let left: Vec<i32> = (0..6).filter(|i| left_bits >> i & 1 == 1).collect();
518	                let right: Vec<i32> = (0..6).filter(|i| right_bits >> i & 1 == 1).collect();
519	                let a = set_of(&left);
520	                let b = set_of(&right);
521	
522	                let union: Vec<i32> = (0..6)
523	                    .filter(|i| (left_bits | right_bits) >> i & 1 == 1)
524	                    .collect();
525	                let inter: Vec<i32> = (0..6)
526	                    .filter(|i| (left_bits & right_bits) >> i & 1 == 1)
527	                    .collect();
528	                let diff: Vec<i32> = (0..6)
529	                    .filter(|i| (left_bits & !right_bits) >> i & 1 == 1)
530	                    .collect();
531	                let sym: Vec<i32> = (0..6)
532	                    .filter(|i| (left_bits ^ right_bits) >> i & 1 == 1)
533	                    .collect();
534	
535	                assert_eq!(a.union_with(&b).to_vec(), union, "{left_bits}|{right_bits}");
536	                assert_eq!(
537	                    a.intersection_with(&b).to_vec(),
538	                    inter,
539	                    "{left_bits}&{right_bits}"
540	                );
541	                assert_eq!(
542	                    a.difference_with(&b).to_vec(),
543	                    diff,
544	                    "{left_bits}-{right_bits}"
545	                );
546	                assert_eq!(
547	                    a.symmetric_difference_with(&b).to_vec(),
548	                    sym,
549	                    "{left_bits}^{right_bits}"
550	                );
551	                assert_eq!(
552	                    a.is_subset_of(&b),
553	                    left_bits & !right_bits == 0,
554	                    "subset {left_bits}/{right_bits}"
555	                );
556	                assert_eq!(
557	                    a.is_disjoint_from(&b),
558	                    left_bits & right_bits == 0,
559	                    "disjoint {left_bits}/{right_bits}"
560	                );
561	            }
562	        }
563	    }
