566	    fn union_of_large_sets_stays_correct() {
567	        let mut s1 = SortedSet::new();
568	        let mut s2 = SortedSet::new();
569	        for i in 0..5000i32 {
570	            s1.insert(i);
571	            s2.insert(i * 2);
572	        }
573	        let s3 = s1.union_with(&s2);
574	        assert_eq!(s1.len(), 5000);
