593	    #[test]
594	    fn conversions_and_traits() {
595	        let set: SortedSet<i32> = vec![3, 1, 2, 1].into_iter().collect();
596	        assert_eq!(set.to_vec(), vec![1, 2, 3]);
597	        assert_eq!(format!("{:?}", set), "{1, 2, 3}");
598	        assert_eq!(set.clone(), set);
599	        assert_eq!(set.as_sorted_list().len(), 3);
600	        assert_eq!(set.iter().copied().collect::<Vec<i32>>(), vec![1, 2, 3]);
601	        assert_eq!(set.into_vec(), vec![1, 2, 3]);
602	
603	        let mut set = SortedSet::<i32>::default();
604	        set.extend([5, 4, 5]);
605	        assert_eq!(set.to_vec(), vec![4, 5]);
606	        assert_eq!(set.load_factor(), DEFAULT_LOAD_FACTOR);
607	        set.clear();
608	        assert!(set.is_empty());
609	    }
610	}
