1	//! A sorted list backed by a two-level list-of-lists layout.
2	//!
3	//! Values live in a `Vec` of sorted sublists, each holding at most `2 * load`
4	//! elements. Because every sublist is small, inserting or removing a value only
5	//! shifts a bounded number of elements instead of the whole sequence.
6	//!
7	//! A positional index tree (a flattened, implicit binary tree of subtree sizes)
8	//! sits on top of the sublists so that lookup by rank -- `get`, `pop`,
9	//! `index_of` -- stays logarithmic rather than scanning every sublist.
10	
11	use std::cmp::Ordering;
12	use std::fmt;
13	use std::ops::Index;
14	
15	/// Default maximum sublist occupancy before a sublist is split in half.
16	pub const DEFAULT_LOAD_FACTOR: usize = 1000;
17	
18	/// A sorted sequence that keeps duplicates.
19	pub struct SortedList<T> {
20	    /// Sorted sublists; concatenating them yields the whole sorted sequence.
21	    /// A sublist is never empty.
22	    lists: Vec<Vec<T>>,
23	    /// Flattened index tree of subtree sizes, or empty when not built.
24	    index: Vec<usize>,
25	    /// Offset of the leaf row (the per-sublist lengths) inside `index`.
26	    offset: usize,
27	    /// Total number of elements.
28	    len: usize,
29	    /// Target sublist occupancy.
30	    load: usize,
31	}
32	
33	impl<T> SortedList<T> {
