// Throwaway black-box differential test: SortedSet vs BTreeSet model.
#[path = "src/lib.rs"]
mod sc;

use sc::SortedSet;
use std::collections::BTreeSet;

fn lcg(state: &mut u64) -> u64 {
    *state = state
        .wrapping_mul(6364136223846793005)
        .wrapping_add(1442695040888963407);
    *state >> 33
}

fn build(values: &[i32], load: usize) -> SortedSet<i32> {
    let mut s = SortedSet::with_load_factor(load);
    for v in values {
        s.insert(*v);
    }
    s
}

fn check_set(tag: &str, s: &SortedSet<i32>, model: &BTreeSet<i32>, lo: i32, hi: i32) {
    let got = s.to_vec();
    let want: Vec<i32> = model.iter().copied().collect();
    assert_eq!(got, want, "{tag}: contents");
    assert_eq!(s.len(), model.len(), "{tag}: len (got {:?})", got);
    // strictly increasing
    for w in got.windows(2) {
        assert!(w[0] < w[1], "{tag}: not strictly increasing: {:?}", got);
    }
    for v in lo..hi {
        assert_eq!(
            s.contains(&v),
            model.contains(&v),
            "{tag}: contains({v}) with {:?}",
            got
        );
    }
    // rank access must agree
    for (i, w) in want.iter().enumerate() {
        assert_eq!(s.get(i), Some(w), "{tag}: get({i})");
    }
    assert_eq!(s.get(want.len()), None, "{tag}: get past end");
    assert_eq!(s.iter().count(), model.len(), "{tag}: iter count");
    for v in lo..hi {
        let bl = want.partition_point(|x| *x < v);
        let br = want.partition_point(|x| *x <= v);
        assert_eq!(s.bisect_left(&v), bl, "{tag}: bisect_left({v})");
        assert_eq!(s.bisect_right(&v), br, "{tag}: bisect_right({v})");
        assert_eq!(
            s.index_of(&v),
            if bl == br { None } else { Some(bl) },
            "{tag}: index_of({v})"
        );
    }
}

// ---------------------------------------------------------------- insert dedup
fn test_insert_every_position() {
    // Exhaustive: every subset of a universe, then insert every universe value
    // (already present or not) and compare against the model. This hits "below
    // all", "above all", "inside a sublist", "at a sublist boundary" and
    // "equal to a sublist maximum" for every load factor.
    for load in 1..=5usize {
        for bits in 0u32..(1 << 8) {
            let base: Vec<i32> = (0..8).filter(|i| bits >> i & 1 == 1).collect();
            for extra in -1..=8i32 {
                for order in 0..3 {
                    let mut vals = base.clone();
                    match order {
                        0 => {}
                        1 => vals.reverse(),
                        _ => vals.rotate_right(base.len() / 2 + usize::from(base.is_empty())),
                    }
                    let mut s = build(&vals, load);
                    let mut m: BTreeSet<i32> = base.iter().copied().collect();
                    let expect_new = !m.contains(&extra);
                    let got_new = s.insert(extra);
                    m.insert(extra);
                    assert_eq!(
                        got_new, expect_new,
                        "load {load} bits {bits} extra {extra}: insert() return"
                    );
                    check_set(
                        &format!("insert load={load} bits={bits} extra={extra} order={order}"),
                        &s,
                        &m,
                        -3,
                        12,
                    );
                    // second insert of the same value must be a no-op
                    assert!(!s.insert(extra), "re-insert reported novel");
                    assert_eq!(s.len(), m.len(), "re-insert changed len");
                }
            }
        }
    }
    println!("insert: every-position exhaustive OK");
}

fn test_insert_random() {
    for load in [1usize, 2, 3, 4, 7, 1000] {
        let mut state = 0xDEADBEEFu64 ^ load as u64;
        let mut s = SortedSet::with_load_factor(load);
        let mut m = BTreeSet::new();
        for step in 0..3000 {
            let v = (lcg(&mut state) % 200) as i32 - 50;
            let expect = m.insert(v);
            let got = s.insert(v);
            assert_eq!(got, expect, "load {load} step {step} value {v}");
            assert_eq!(s.len(), m.len(), "load {load} step {step}");
        }
        check_set(&format!("random insert load={load}"), &s, &m, -60, 160);
    }
    println!("insert: randomized OK");
}

// ------------------------------------------------------------------- union etc.
fn ops_check(tag: &str, a_vals: &[i32], b_vals: &[i32], load: usize, lo: i32, hi: i32) {
    let a = build(a_vals, load);
    let b = build(b_vals, load);
    let ma: BTreeSet<i32> = a_vals.iter().copied().collect();
    let mb: BTreeSet<i32> = b_vals.iter().copied().collect();

    let a_before = a.to_vec();
    let b_before = b.to_vec();
    let (alen, blen) = (a.len(), b.len());

    let u = a.union_with(&b);
    let i = a.intersection_with(&b);
    let d = a.difference_with(&b);
    let x = a.symmetric_difference_with(&b);

    // inputs untouched
    assert_eq!(a.to_vec(), a_before, "{tag}: lhs mutated");
    assert_eq!(b.to_vec(), b_before, "{tag}: rhs mutated");
    assert_eq!((a.len(), b.len()), (alen, blen), "{tag}: input len changed");

    check_set(&format!("{tag} union"), &u, &ma.union(&mb).copied().collect(), lo, hi);
    check_set(
        &format!("{tag} inter"),
        &i,
        &ma.intersection(&mb).copied().collect(),
        lo,
        hi,
    );
    check_set(
        &format!("{tag} diff"),
        &d,
        &ma.difference(&mb).copied().collect(),
        lo,
        hi,
    );
    check_set(
        &format!("{tag} sym"),
        &x,
        &ma.symmetric_difference(&mb).copied().collect(),
        lo,
        hi,
    );

    // union must be symmetric and idempotent, and further usable
    assert_eq!(b.union_with(&a).to_vec(), u.to_vec(), "{tag}: union asymmetric");
    let mut u2 = u.clone();
    for v in lo..hi {
        let expect = !u2.contains(&v);
        assert_eq!(u2.insert(v), expect, "{tag}: post-union insert({v})");
    }
    let mut all: BTreeSet<i32> = ma.union(&mb).copied().collect();
    all.extend(lo..hi);
    check_set(&format!("{tag} union+inserts"), &u2, &all, lo - 2, hi + 2);
}

fn test_ops_exhaustive() {
    // All subset pairs of an 7-element universe: disjoint, identical, nested,
    // interleaved, one empty, both empty, singletons -- all covered.
    for load in 1..=4usize {
        for lb in 0u32..(1 << 7) {
            for rb in 0u32..(1 << 7) {
                let l: Vec<i32> = (0..7).filter(|i| lb >> i & 1 == 1).collect();
                let r: Vec<i32> = (0..7).filter(|i| rb >> i & 1 == 1).collect();
                ops_check(&format!("ex load={load} {lb}/{rb}"), &l, &r, load, 0, 7);
            }
        }
    }
    println!("set ops: exhaustive over 2^7 x 2^7 subset pairs, loads 1..4 OK");
}

fn test_ops_random() {
    for load in [1usize, 2, 3, 5, 9, 16] {
        let mut state = 0x1234_5678_9ABC_DEF0u64 ^ (load as u64 * 31);
        for trial in 0..400 {
            let na = (lcg(&mut state) % 60) as usize;
            let nb = (lcg(&mut state) % 60) as usize;
            let span = 1 + (lcg(&mut state) % 90) as i32;
            let a: Vec<i32> = (0..na).map(|_| (lcg(&mut state) % span as u64) as i32).collect();
            let b: Vec<i32> = (0..nb).map(|_| (lcg(&mut state) % span as u64) as i32).collect();
            ops_check(
                &format!("rand load={load} trial={trial}"),
                &a,
                &b,
                load,
                -2,
                span + 2,
            );
        }
    }
    println!("set ops: randomized OK");
}

fn test_mixed_load_factors() {
    // union_with reads other's iterator only; a different load on the rhs must
    // not matter, and the result inherits self's load.
    for (la, lb) in [(1usize, 7usize), (7, 1), (2, 3), (1000, 1)] {
        let a = build(&(0..50).collect::<Vec<i32>>(), la);
        let b = build(&(0..50).map(|i| i * 3).collect::<Vec<i32>>(), lb);
        let u = a.union_with(&b);
        let mut m: BTreeSet<i32> = (0..50).collect();
        m.extend((0..50).map(|i| i * 3));
        check_set(&format!("mixed {la}/{lb}"), &u, &m, -2, 160);
        assert_eq!(u.load_factor(), la, "result load factor");
    }
    println!("set ops: mixed load factors OK");
}

fn test_test6_scenario() {
    for n in 0..300i32 {
        for load in [1usize, 2, 3, 1000] {
            let mut s1 = SortedSet::with_load_factor(load);
            let mut s2 = SortedSet::with_load_factor(load);
            for i in 0..n {
                s1.insert(i);
                s2.insert(i.wrapping_mul(2));
            }
            let s3 = s1.union_with(&s2);
            let m1: BTreeSet<i32> = (0..n).collect();
            let m2: BTreeSet<i32> = (0..n).map(|i| i.wrapping_mul(2)).collect();
            let m3: BTreeSet<i32> = m1.union(&m2).copied().collect();
            assert_eq!(s1.len(), m1.len(), "n={n} load={load} s1");
            assert_eq!(s2.len(), m2.len(), "n={n} load={load} s2");
            assert_eq!(s3.len(), m3.len(), "n={n} load={load} s3");
            assert_eq!(s3.to_vec(), m3.iter().copied().collect::<Vec<i32>>());
            for i in 0..n {
                assert!(s3.contains(&i), "n={n} load={load} contains({i})");
            }
        }
    }
    println!("test6 scenario: n in 0..300 x loads OK");
}

fn test_negative_and_extremes() {
    let vals = [i32::MIN, i32::MIN + 1, -1, 0, 1, i32::MAX - 1, i32::MAX];
    for load in 1..=3usize {
        for lb in 0u32..(1 << vals.len()) {
            for rb in 0u32..(1 << vals.len()) {
                let l: Vec<i32> = (0..vals.len()).filter(|i| lb >> i & 1 == 1).map(|i| vals[i]).collect();
                let r: Vec<i32> = (0..vals.len()).filter(|i| rb >> i & 1 == 1).map(|i| vals[i]).collect();
                let a = build(&l, load);
                let b = build(&r, load);
                let ma: BTreeSet<i32> = l.iter().copied().collect();
                let mb: BTreeSet<i32> = r.iter().copied().collect();
                let u = a.union_with(&b);
                let want: Vec<i32> = ma.union(&mb).copied().collect();
                assert_eq!(u.to_vec(), want, "extremes load={load} {lb}/{rb}");
                assert_eq!(u.len(), want.len());
                for v in vals {
                    assert_eq!(u.contains(&v), ma.contains(&v) || mb.contains(&v));
                }
            }
        }
    }
    println!("extremes: i32::MIN/MAX OK");
}

fn test_big_union_shape() {
    // Large, forces many sublist splits and index rebuilds.
    let mut s1 = SortedSet::new();
    let mut s2 = SortedSet::new();
    for i in 0..20000i32 {
        s1.insert(i);
        s2.insert(i * 2);
    }
    let s3 = s1.union_with(&s2);
    assert_eq!(s1.len(), 20000);
    assert_eq!(s2.len(), 20000);
    assert_eq!(s3.len(), 30000);
    let v = s3.to_vec();
    for w in v.windows(2) {
        assert!(w[0] < w[1]);
    }
    assert_eq!(v.len(), s3.len());
    for i in 0..20000i32 {
        assert!(s3.contains(&i), "contains({i})");
    }
    for i in 20000..40000i32 {
        assert_eq!(s3.contains(&i), i % 2 == 0, "contains({i})");
    }
    println!("large union: OK");
}

fn main() {
    test_insert_every_position();
    test_insert_random();
    test_ops_exhaustive();
    test_ops_random();
    test_mixed_load_factors();
    test_test6_scenario();
    test_negative_and_extremes();
    test_big_union_shape();
    println!("ALL BRUTE-FORCE CHECKS PASSED");
}

