// Supplementary audit: aliasing, non-Copy T, algebraic identities, load=1 stress.
#[path = "src/lib.rs"]
mod sc;

use sc::SortedSet;
use std::collections::BTreeSet;

fn lcg(state: &mut u64) -> u64 {
    *state = state
        .wrapping_mul(6364136223846793005)
        .wrapping_add(1442695040888963407);
    *state >> 33
}

fn build(vals: &[i32], load: usize) -> SortedSet<i32> {
    let mut s = SortedSet::with_load_factor(load);
    for v in vals {
        s.insert(*v);
    }
    s
}

fn main() {
    // 1. self-aliased union: a.union_with(&a) must equal a, and must not mutate a.
    for load in 1..=4usize {
        for bits in 0u32..(1 << 9) {
            let vals: Vec<i32> = (0..9).filter(|i| bits >> i & 1 == 1).collect();
            let a = build(&vals, load);
            let before = a.to_vec();
            let u = a.union_with(&a);
            assert_eq!(a.to_vec(), before, "self-union mutated lhs");
            assert_eq!(u.to_vec(), before, "self-union changed contents");
            assert_eq!(u.len(), before.len(), "self-union len");
            assert_eq!(a.intersection_with(&a).to_vec(), before);
            assert!(a.difference_with(&a).is_empty());
            assert!(a.symmetric_difference_with(&a).is_empty());
            assert_eq!(a.difference_with(&a).len(), 0);
            assert_eq!(a.symmetric_difference_with(&a).len(), 0);
        }
    }
    println!("self-aliased union/intersection/difference OK");

    // 2. non-Copy, non-numeric T: Clone path in merge_walk.
    let mut sa: SortedSet<String> = SortedSet::with_load_factor(2);
    let mut sb: SortedSet<String> = SortedSet::with_load_factor(3);
    let wa = ["pear", "apple", "fig", "apple", "kiwi"];
    let wb = ["fig", "banana", "kiwi", "zucchini"];
    for w in wa {
        sa.insert(w.to_string());
    }
    for w in wb {
        sb.insert(w.to_string());
    }
    let su = sa.union_with(&sb);
    let ma: BTreeSet<String> = wa.iter().map(|s| s.to_string()).collect();
    let mb: BTreeSet<String> = wb.iter().map(|s| s.to_string()).collect();
    let mu: Vec<String> = ma.union(&mb).cloned().collect();
    assert_eq!(su.to_vec(), mu);
    assert_eq!(su.len(), mu.len());
    assert_eq!(sa.len(), ma.len(), "lhs mutated");
    assert_eq!(sb.len(), mb.len(), "rhs mutated");
    for w in wa.iter().chain(wb.iter()) {
        assert!(su.contains(&w.to_string()), "contains({w})");
    }
    assert!(!su.contains(&"quince".to_string()));
    println!("non-Copy T OK: {:?}", su.to_vec());

    // 3. algebraic identities over random triples.
    let mut state = 0xFEEDFACEu64;
    for trial in 0..600 {
        let load = 1 + (lcg(&mut state) % 6) as usize;
        let mk = |st: &mut u64| -> Vec<i32> {
            let n = (lcg(st) % 40) as usize;
            (0..n).map(|_| (lcg(st) % 50) as i32).collect()
        };
        let av = mk(&mut state);
        let bv = mk(&mut state);
        let cv = mk(&mut state);
        let a = build(&av, load);
        let b = build(&bv, load);
        let c = build(&cv, load);

        // (a|b)|c == a|(b|c)
        let l = a.union_with(&b).union_with(&c);
        let r = a.union_with(&b.union_with(&c));
        assert_eq!(l.to_vec(), r.to_vec(), "trial {trial}: union not associative");
        // a|b == b|a
        assert_eq!(a.union_with(&b).to_vec(), b.union_with(&a).to_vec());
        // a == (a&b) | (a-b)
        let recon = a.intersection_with(&b).union_with(&a.difference_with(&b));
        assert_eq!(recon.to_vec(), a.to_vec(), "trial {trial}: a != (a&b)|(a-b)");
        // a^b == (a-b) | (b-a)
        let sym = a.difference_with(&b).union_with(&b.difference_with(&a));
        assert_eq!(
            sym.to_vec(),
            a.symmetric_difference_with(&b).to_vec(),
            "trial {trial}: sym mismatch"
        );
        // subset / disjoint agree with the model
        let ma: BTreeSet<i32> = av.iter().copied().collect();
        let mb: BTreeSet<i32> = bv.iter().copied().collect();
        assert_eq!(a.is_subset_of(&b), ma.is_subset(&mb), "trial {trial}: subset");
        assert_eq!(b.is_superset_of(&a), ma.is_subset(&mb));
        assert_eq!(
            a.is_disjoint_from(&b),
            ma.is_disjoint(&mb),
            "trial {trial}: disjoint"
        );
        // len must equal the number of iterated items for every result
        for s in [&l, &r, &recon, &sym] {
            assert_eq!(s.len(), s.iter().count(), "trial {trial}: len != iter count");
        }
    }
    println!("algebraic identities + subset/disjoint OK");

    // 4. load = 1 stress: maximum number of sublists, i.e. maximum splitting.
    let mut s1 = SortedSet::with_load_factor(1);
    let mut s2 = SortedSet::with_load_factor(1);
    for i in 0..4000i32 {
        s1.insert(i);
        s2.insert(i * 2);
    }
    let s3 = s1.union_with(&s2);
    assert_eq!((s1.len(), s2.len(), s3.len()), (4000, 4000, 6000));
    let v = s3.to_vec();
    assert_eq!(v.len(), 6000);
    for w in v.windows(2) {
        assert!(w[0] < w[1]);
    }
    for i in 0..4000i32 {
        assert!(s3.contains(&i));
    }
    assert_eq!(s3.load_factor(), 1);
    println!("load=1 stress OK");

    // 5. negatives mixed in (what test6 sees once i*2 wraps) -- union across sign.
    for load in [1usize, 2, 1000] {
        let mut a = SortedSet::with_load_factor(load);
        let mut b = SortedSet::with_load_factor(load);
        let mut m = BTreeSet::new();
        for i in 0..3000i32 {
            let x = if i % 2 == 0 { i } else { -i };
            let y = i.wrapping_mul(1_000_003);
            a.insert(x);
            b.insert(y);
            m.insert(x);
            m.insert(y);
        }
        let u = a.union_with(&b);
        assert_eq!(u.len(), m.len(), "load={load}");
        assert_eq!(u.to_vec(), m.iter().copied().collect::<Vec<i32>>());
        for probe in [i32::MIN, -1, 0, 1, i32::MAX] {
            assert_eq!(u.contains(&probe), m.contains(&probe));
        }
    }
    println!("signed / wrapped values OK");

    println!("ALL SUPPLEMENTARY CHECKS PASSED");
}
